INSERT INTO incidents (id, project, title, symptoms, root_cause, service, severity, tags, occurred_at, created_at, embedding, feedback) VALUES ('1e7223d6-7b55-55a2-b7c5-e78d58d2278e', 'sample', 'payment.retry storm during payment-gateway provider outage', 'PagerDuty fired on an elevated `checkout.payment_failed` rate. Logs showed repeated `payment.retry order_id=... attempt=n/8 backoff=...s` climbing through all 8 attempts, followed by `payment.exhausted order_id=... attempts=8` and `checkout.payment_failed order_id=... err=GatewayTimeout`. Customers saw checkout errors and support was flooded with tickets.', 'The upstream payment-gateway provider suffered a partial outage, causing `PaymentClient._call_gateway` to exceed `PAYMENT_GATEWAY_TIMEOUT_SECONDS` on a large fraction of calls. `PaymentClient.charge` exhausted all `PAYMENT_MAX_RETRIES` (8) attempts with exponential backoff before giving up, producing the payment.exhausted signal for affected orders.', 'payment-gateway', 'SEV1', '{"payment-gateway","retry-storm","payment-retry","gateway-timeout"}', '2025-10-12 09:05:00+00:00', '2026-08-19 13:42:17.957399+00:00', '[-0.013478006,-0.0064681508,-0.030429324,0.080759145,-0.02353339,-0.04318516,-0.005124702,-0.036459986,0.034088533,0.05385799,-0.02545628,0.019229496,0.01548545,0.025628597,-0.042860445,0.0011217748,-0.0216412,-0.006239544,-0.0137159815,0.02977088,0.0005842854,-0.024333918,-0.03368024,0.010336712,-0.008441967,0.023855548,-0.00054596335,-0.017172549,0.070413016,0.037778296,-0.014829787,-0.038501225,0.0033307567,-0.019979414,-0.035886936,0.0049121184,-0.008656973,-0.018508598,-0.035278488,-0.067734666,-0.00025404154,0.0010784498,0.012686079,-0.015494705,-0.048075892,-0.041471276,-0.014835936,0.015708428,0.022278728,-0.033173,-0.0153674465,0.00078924396,-0.014482837,-0.01258141,-0.032042235,-0.0260919,0.024835333,-0.028614687,-0.045043305,-0.020587655,0.009090579,-0.041146215,0.014243413,-0.044474594,0.02894031,0.007171885,-0.056574643,0.0034014098,-0.020