INSERT INTO incidents (id, project, title, symptoms, root_cause, service, severity, tags, occurred_at, created_at, embedding, feedback) VALUES ('25dd5cb5-0180-533e-bc8f-98c43739bd11', 'sample', 'fulfillment.queue.full — fulfillment-worker deployment down, zero drain', 'FulfillmentQueue.depth() climbed steadily with zero drain over roughly an hour, eventually hitting `fulfillment.queue.full depth=5000 max=5000` and triggering `checkout.enqueue_failed` errors. Unlike a normal traffic-driven fill, the enqueue rate itself was unremarkable — nothing was consuming from the queue at all.', 'The fulfillment-worker deployment (the downstream queue consumer, external to checkout_service) had crashed and its pods failed to restart due to an unrelated infrastructure issue, so nothing was consuming from the queue while checkout continued enqueueing normally.', 'fulfillment-worker', 'SEV2', '{"fulfillment-worker","queue-full","outage","downstream"}', '2026-06-11 19:22:00+00:00', '2026-08-19 13:42:18.730363+00:00', '[0.023303926,0.038934316,-0.013125844,0.0410987,-0.06536991,-0.031894088,0.029410224,0.019771628,0.00101735,0.07981403,-0.016158413,0.034433864,0.0072231838,0.011226433,-0.04673333,-0.0045283935,0.004390357,-0.013098536,-0.05619223,-0.015301883,0.010277211,-0.007336855,-0.058296073,0.014890724,-0.04202868,0.067451455,0.01182249,0.00042577216,0.075568765,0.07166008,-0.05243272,0.01928947,0.010745849,-0.060585883,0.009332702,-0.011644754,-0.006408987,0.011006905,-0.011190078,-0.0778936,0.012084333,-0.017591164,-0.011061341,-0.0503704,-0.063067004,-0.01614646,0.02746535,0.017201161,-0.003709485,-0.024839295,-0.011345056,0.021486813,0.017536093,-0.062208667,0.039506707,-0.011504095,0.011326557,-0.008434587,-0.02284884,0.012315746,0.035997003,0.0020014085,0.009214978,-0.030390596,0.032059535,0.04440702,-0.04760794,-0.009979099,-0.01848753,-0.0024313126,-0.019600974,0.011993817,-0.013776822,-0.025197094,0.0025818949,-0.022406567,0.016583351,0.0027593449,0.017930657,-0.002066