INSERT INTO incidents (id, project, title, symptoms, root_cause, service, severity, tags, occurred_at, created_at, embedding, feedback) VALUES ('5a77bbb3-8a19-52f7-84b5-1fb021b02085', 'sample', 'checkout-handler CrashLoopBackOff after deploy — broken import', 'Immediately after a deploy, all checkout-handler pods entered CrashLoopBackOff. checkout-api returned 503s for every request, and `api.error path=/checkout` showed connection-refused failures rather than application-level errors, indicating checkout-handler itself was never coming up.', 'The deploy included a change to checkout.py with a broken import referencing a module path that didn''t exist in the built container image, causing CheckoutHandler''s process to fail at startup before it could serve any traffic.', 'checkout-handler', 'SEV1', '{"bad-deploy","crash-loop","checkout-handler","rollback"}', '2026-05-20 15:05:00+00:00', '2026-08-19 13:42:18.645270+00:00', '[0.0037578125,-0.006862233,-0.019665971,0.046470907,-0.01807222,-0.047860745,0.03246488,0.011541408,0.062498692,0.06034107,-0.010393762,0.019940605,0.0180188,-0.0189101,-0.06002213,0.04036581,0.014013858,0.01186194,-0.02611778,0.0012917566,0.023331227,-0.03670983,-0.04127311,0.010133505,-0.055677842,0.04400834,-0.0018770116,-0.03297076,0.07319638,0.026987873,-0.03667251,-0.0039578923,0.00021916187,-0.04515718,0.014426229,0.021933846,0.010984683,0.00452735,-0.01172444,-0.05749955,-0.0030280047,-0.023807436,0.042740326,-0.034162052,-0.049677037,-0.0035895198,-0.009185365,-0.030786525,-3.2939824e-05,-0.05053725,-0.019623969,0.024508152,-0.0029659076,-0.0054271347,-0.028343992,-0.0066588414,0.00486282,0.010380153,-0.004896719,-0.025461415,-0.012144719,0.0042032143,0.018982323,-0.03415567,0.014426789,-0.0019564007,-0.052357413,-0.0002734683,0.014984175,0.018586187,-0.068677865,0.06825615,-0.014535211,-0.07070801,0.009076741,0.01925364,-0.03523632,0.012380148,-0.012422356,0.020442026,-0.00051876175,0.034898665,0.0537129,-0.026324546,-0.0151903685,-0.0027