INSERT INTO incidents (id, project, title, symptoms, root_cause, service, severity, tags, occurred_at, created_at, embedding, feedback) VALUES ('7c0ceb99-d72d-5f20-8c1f-2138b71a4a47', 'sample', 'Checkout failures during flash-sale traffic spike — db.pool.exhausted', 'checkout-api alerts fired for elevated 5xx during a flash-sale traffic spike. checkout-handler logs showed repeated `db.pool.exhausted in_use=10 size=10` immediately followed by `checkout.payment_failed order_id=... err=ConnectionPoolExhausted`. Customers reported checkout failures and spinning carts. On-call initially suspected the database itself was undersized for peak load.', 'Not fully identified at the time. On-call verified actual connection counts on the database side were well below its real ceiling, ruling out true DB capacity limits, but could not determine why the application-side pool still drained completely under load. Closed as mitigated via pool size increase and load shedding; true root cause was left as ''connection pool sizing marginal for peak traffic'' with a follow-up investigation ticket that was never completed.', 'connection-pool', 'SEV1', '{"connection-pool","db-pool-exhausted","traffic-spike","unresolved-root-cause","checkout"}', '2025-11-03 14:12:00+00:00', '2026-08-19 13:42:17.725719+00:00', '[-0.0070851855,0.031180572,-0.016710522,0.037442375,-0.0005105626,-0.035158925,0.049115457,-0.03987366,0.032281857,0.063450254,0.01849379,0.030352354,0.008504023,-0.009651098,-0.051203728,0.005865356,-0.0103266025,-0.01704222,-0.028426206,-0.01833455,0.026947103,-0.016261332,-0.058518466,0.018834906,-0.030535823,0.029060218,-0.013539816,-0.0335771,0.08329967,0.02559847,-0.03171932,-0.0127478605,0.013824571,-0.023740096,-0.0026810463,0.0069382284,-0.003283494,-0.040618956,-0.023050167,-0.06783896,-0.023832591,0.02302892,0.030902678,-0.04552278,-0.04212797,-0.019592222,-0.0026805424,-0.022034483,0.0130841965,-0.04764875,-0.03502274,0.0070843897,-0.014705692,-0.02332244,-0.0063946983,-0.0