INSERT INTO incidents (id, project, title, symptoms, root_cause, service, severity, tags, occurred_at, created_at, embedding, feedback) VALUES ('98d7bf23-3028-57e9-b69f-5cde02b070e8', 'sample', 'Customers report slow checkout — latency dashboards green, no alert fired', 'Support tickets and Slack reports described checkout ''taking forever'' or the spinner hanging, but the checkout latency dashboard (`metrics.latency name=checkout.duration agg=avg`) stayed within normal bounds the entire time and no alert fired. On-call was paged by a manager escalation rather than an alert, checked `api.request` / `api.error` logs and saw no elevated error rate, and confirmed `CheckoutAPI.get_health` returned healthy throughout.', 'Unable to reproduce or correlate against any internal signal — every monitored aggregate looked nominal for the entire reported window. Closed as ''could not reproduce — dashboards nominal'', with a note for next time to collect specific order_ids from affected customers so individual checkout.start/checkout.success timestamps could be traced directly.', 'checkout-handler', 'SEV2', '{"latency","customer-reported","dashboards-green","unresolved","checkout"}', '2026-08-09 16:40:00+00:00', '2026-08-19 13:42:17.843533+00:00', '[-0.023013493,0.004971418,-0.055745654,0.07540998,-0.008870451,-0.015522092,0.04289087,-0.005582831,0.044923045,0.06881167,-0.015279786,0.010069366,-0.04399556,-0.03147213,-0.049717754,-0.0010919761,0.03334937,-0.0025293946,-0.023127105,0.0026277937,0.019065605,-0.005284929,-0.06687037,0.0032740876,-0.057463355,0.022846228,-0.016427772,-0.017899549,0.07259832,0.060073804,-0.017995311,-0.016568447,0.010762877,-0.021746637,0.020943254,-0.004924014,-0.0009183926,-0.03153275,-0.025319172,-0.06858679,-0.015625399,0.016838012,0.008108476,-0.01565196,-0.030322587,-0.034307085,-0.012906434,0.0033294898,0.007921072,-0.065274164,0.011626326,0.015058827,-0.017992217,-0.032752413,-0.036139302,-0.040214453,0.002367186,0.00016744123,0.0026078925,0.0