INSERT INTO incidents (id, project, title, symptoms, root_cause, service, severity, tags, occurred_at, created_at, embedding, feedback) VALUES ('b6760c17-f4ba-5516-a3e3-d5f9738c04e2', 'sample', 'Checkout failures spike after deploy — PAYMENT_MAX_RETRIES misconfigured to 1', 'checkout.payment_failed rate jumped immediately after a routine deploy. Logs showed `payment.exhausted order_id=... attempts=1` right after the corresponding `payment.call` line, with no `payment.retry` entries in between. The `config.loaded` log line on the new pods read `payment_max_retries=1` instead of the expected 8.', 'The deploy shipped a config.py change that accidentally set PAYMENT_MAX_RETRIES=1 during an unrelated config refactor, so transient gateway blips that would normally succeed on retry now failed checkout immediately.', 'checkout-handler', 'SEV2', '{"config-regression","bad-deploy","payment-retries","checkout"}', '2026-01-18 10:02:00+00:00', '2026-08-19 13:42:18.164422+00:00', '[0.004064963,0.020677883,-0.05258895,0.08774632,-0.020574268,-0.078840576,0.008623211,-0.027158989,0.031181538,0.06289116,0.0008848273,0.036665663,0.045647997,0.016741626,-0.0507053,0.0071775457,-0.0056740493,-0.0066911243,-0.013739408,0.00893323,0.0006162186,-0.04141866,-0.0480026,0.043495774,-0.06256328,0.058181647,-0.016684147,-0.025468186,0.08604443,0.038484715,-0.010910212,0.003955105,0.01049948,-0.022438733,-0.021520758,-0.009885684,0.008619255,-0.007980325,-0.017981112,-0.078683004,0.0038865388,-0.0035749727,0.01899037,-0.019514302,-0.04504254,-0.026290568,-0.032177303,-0.024240136,0.015849367,-0.032024156,-0.030212218,-0.015257373,-0.019853363,0.0053497674,-0.029092923,-0.008005609,0.0031242825,-0.035887185,-0.04745876,-0.02815685,0.025810845,-0.0045733172,-0.009811517,-0.030382384,0.022973198,0.005011017,-0.056328043,-0.0038099461,0.003020896,0.015019093,-0.0036551731,0.04997282,0.02149849,-0.047070794,-0.016733611,0.009099891,-0.011860916,-0.03591335,-0.00530164,0.036008652,0.009715136,0.01449