INSERT INTO incidents (id, project, title, symptoms, root_cause, service, severity, tags, occurred_at, created_at, embedding, feedback) VALUES ('ca2f2071-518a-5310-ad5d-329dca7fc23a', 'sample', 'checkout-handler pods evicted — disk full from leftover debug logging', 'CheckoutAPI.get_health checks started failing intermittently as checkout-handler pods were evicted. `kubectl describe pod` showed DiskPressure evictions. There was no unusual application-level log signal — the issue was infrastructure-level disk exhaustion, not a code path problem.', 'A debug-level logging flag enabled during a prior investigation was never reverted, filling local pod disk with verbose logs over several days until kubelet evicted pods under DiskPressure.', 'checkout-handler', 'SEV2', '{"disk","infra","checkout-handler","crash-loop"}', '2026-04-02 02:20:00+00:00', '2026-08-19 13:42:18.553844+00:00', '[-0.002885985,-0.027284117,-0.0021809305,0.08502993,-0.00055072043,-0.041051753,0.022596864,0.014212867,0.01794289,0.074397266,0.024841059,-0.017615099,0.02703212,-0.015074835,-0.058880653,0.029069558,0.01343151,0.02133211,-0.052846905,0.017958142,0.027856506,-0.031822935,-0.03654042,0.013671356,-0.04825253,0.0232839,0.014395319,-0.041241437,0.082038924,0.05331228,-0.05104535,-0.02168884,0.017960042,-0.05585621,0.003080501,-0.042027026,-0.0013172649,-0.00045574488,-0.015157394,-0.0633335,0.001981927,0.009465101,0.06495629,-0.041724835,-0.0052014613,-0.01579628,-0.019375876,-0.00058859953,0.010523985,0.0012105104,-0.0077627297,0.0047502727,-0.03337312,-0.022253005,-0.035571028,0.014367964,-0.023811791,0.017778452,-0.019075727,-0.025581319,-0.010213079,0.018047532,0.040338855,-0.041764528,0.025811907,0.04782022,-0.06589453,-0.017112456,-0.019573318,0.005205788,-0.022755554,0.03522062,-0.0375104,-0.087032944,-0.044471096,-0.008661134,-0.014264516,0.0060896478,0.041810453,0.042867426,0.049162876,0.029494587,0.028523562,-0.0005077725,-0.044213515,-0.01988177,0.029910462,-0.0140745565,0.0040603424