INSERT INTO incidents (id, project, title, symptoms, root_cause, service, severity, tags, occurred_at, created_at, embedding, feedback) VALUES ('f87837a4-b610-59b0-9abe-99c8f98957c9', 'sample', 'payment.retry storm amplified by too-aggressive backoff configuration', 'During a minor payment-gateway blip, `payment.retry` volume was far higher than the size of the blip should have caused — retries were hammering the gateway in rapid succession rather than backing off, and `payment.exhausted` counts climbed faster than expected for the underlying issue.', 'A prior config change had set PAYMENT_BASE_DELAY_SECONDS too low (0.05s instead of the intended 0.5s), so PaymentClient.charge''s exponential backoff barely delayed between attempts, amplifying load on an already-degraded gateway.', 'payment-gateway', 'SEV2', '{"payment-retry","backoff","config","retry-storm"}', '2026-02-27 12:35:00+00:00', '2026-08-19 13:42:18.930136+00:00', '[-0.0058100987,0.02064618,-0.025585333,0.08156775,-0.060632747,-0.05077121,0.0027981077,-0.04956001,-0.002945146,0.070426606,0.001394277,0.04852173,0.008828332,-0.0055635716,-0.048036937,0.008490258,-0.037854552,-0.04177371,-0.03409506,0.010157001,-0.027756412,-0.059355106,-0.0079827905,0.012464492,-0.009778182,0.039696783,-0.0081910435,-0.011986162,0.066479295,0.043789823,-0.008402681,-0.024837423,-0.0037846558,-0.007205681,-0.055307236,-0.031115456,0.008435592,-0.035530675,-0.029616762,-0.08276787,0.016757,-0.0467058,0.013431163,-0.04470466,-0.04538774,-0.02326319,-0.018633675,-0.0030054133,0.018028717,-0.023110146,-0.03148979,-0.011814077,-0.020872876,-0.00604074,-0.037242897,-0.011109115,0.005691434,-0.0050496017,-0.021635221,-0.024695013,0.01053305,-0.0051873545,0.030657599,-0.04811715,0.026529422,0.026342703,-0.040356476,-0.019654755,-0.030386135,0.022855805,-0.013512079,0.029869577,0.011469529,-0.030139359,-0.018312093,0.033038374,-0.017975196,-0.0020936567,-0.009657025,0.023564136,-0.016891602,0.033117782,0.014849696,-0.0028813449,-0.023