INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('0239d4fb-0059-485d-9e29-2dcbb32d67cf', 'b6760c17-f4ba-5516-a3e3-d5f9738c04e2', 3, 'Added a config validation check to the deploy pipeline asserting PAYMENT_MAX_RETRIES stays within an expected 5-10 range', NULL, 'Prevents future accidental low-retry deploys from reaching production');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('0424de74-dddc-4ca0-9720-afc5fdc75053', '98d7bf23-3028-57e9-b69f-5cde02b070e8', 3, 'Checked CheckoutAPI.get_health status over the window', NULL, 'Health checks passed continuously; no service-level degradation indicated');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('0c5905a7-077a-4698-8121-1ea01a9d6fda', 'aac040e7-1280-5f79-871d-dc07c9f66450', 3, 'Fixed the auto-renewal cronjob and added an alert 14 days before certificate expiry', NULL, 'Prevents future silent renewal failures from reaching expiry');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('1474edee-a62a-42d5-93fe-bd3c7929801c', '5a77bbb3-8a19-52f7-84b5-1fb021b02085', 2, 'Rolled back the deploy immediately', 'kubectl rollout undo deployment checkout-handler', 'Pods returned to Running; checkout-api 503s stopped within about 2 minutes');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('1b3c91b0-524e-4c2b-918b-e0e07f4f0d62', '25dd5cb5-0180-533e-bc8f-98c43739bd11', 3, 'Monitored FulfillmentQueue.depth() until it returned to near-zero baseline', NULL, 'Confirmed full recovery; queue held orders rather than dropping them, so no orders were lost');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('233525a8-0317-41cb-82bb-c8c8dfba8ee7', '1e7223d6-7b55-55a2-b7c5-e78d58d2278e', 2, 'Communicated the outage status to support so agents could set customer expectations', NULL, 'Reduced duplicate ticket volume during the outage');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('25fe3f20-2b42-4367-85c6-053982642855', '98d7bf23-3028-57e9-b69f-5cde02b070e8', 1, 'Reviewed the checkout latency dashboard for the reported time window', NULL, 'Average latency (metrics.latency name=checkout.duration agg=avg) was within normal range — no anomaly visible');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('2695e697-6fc8-46c0-b903-bedf46c47679', '845e68dd-ab1c-527b-a154-a48e5dbb392c', 2, 'Rolled back the deploy', 'kubectl rollout undo deployment checkout-handler', 'DB_POOL_SIZE restored to 10; db.pool.exhausted stopped immediately');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('271f00a5-d536-41ce-ae92-b0a7b3ece010', 'ca2f2071-518a-5310-ad5d-329dca7fc23a', 1, 'Checked node conditions for evicted pods', 'kubectl describe node <node> | grep DiskPressure', 'Confirmed DiskPressure-triggered eviction, not an application crash');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('310a4532-6942-4b90-a211-dda99da85149', 'ca2f2071-518a-5310-ad5d-329dca7fc23a', 3, 'Added a log-level revert reminder to the debugging runbook and a disk-usage alert at 80%', NULL, 'Prevents future debug-logging leftovers from silently filling disk');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('3118e20b-8afe-4727-a9ef-28d621476741', '98d7bf23-3028-57e9-b69f-5cde02b070e8', 5, 'Closed the incident as could not reproduce', NULL, 'No fix applied; recommendation left to capture order_ids on any future recurrence of this complaint');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('4350a893-db0c-4c19-8ca3-909d4c5ca8a0', '845e68dd-ab1c-527b-a154-a48e5dbb392c', 1, 'Checked the config.loaded log line on freshly deployed pods', 'grep ''config.loaded'' checkout-handler.log', 'Confirmed pool_size=3 instead of the expected 10');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('4753c94f-3c0b-4ec8-a2d8-d05e60c77334', '1e7223d6-7b55-55a2-b7c5-e78d58d2278e', 4, 'Added a dashboard alert on sustained payment.exhausted rate to page on-call faster during future provider-side degradations', NULL, 'Future gateway outages of this scale will be detected within minutes instead of via customer tickets');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('4cb12fc6-2b03-4394-86aa-e0d95dd9692a', 'b6760c17-f4ba-5516-a3e3-d5f9738c04e2', 1, 'Diffed the new config.loaded log output against the previous deploy''s baseline', 'grep ''config.loaded'' checkout-handler.log', 'Found payment_max_retries=1 instead of the expected 8');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('55e94e0e-1419-4139-b4bc-a7e4e2ed3954', '3d877d0d-f7de-5aea-83d0-e2a637c109b0', 3, 'Documented the probe tuning rationale in the on-call runbook', NULL, 'Prevents future over-aggressive probe settings from being reintroduced');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('577ea974-2813-486b-a78a-005d38c14d10', '7c0ceb99-d72d-5f20-8c1f-2138b71a4a47', 1, 'Confirmed the alert signal via checkout-handler logs', 'grep ''db.pool.exhausted'' checkout-handler.log', 'Verified repeated db.pool.exhausted in_use=10 size=10 during the traffic spike window');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('5a754efa-df79-4f83-9520-56a78fffa1c8', '7c0ceb99-d72d-5f20-8c1f-2138b71a4a47', 2, 'Checked database-side connection metrics to rule out real DB capacity limits', NULL, 'DB connection count was far below its actual ceiling — database itself was not the bottleneck');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('6003902e-a28c-4ff5-9c61-f520e9fa05ab', 'f87837a4-b610-59b0-9abe-99c8f98957c9', 2, 'Corrected the backoff base delay', 'edit config.py: PAYMENT_BASE_DELAY_SECONDS = 0.5', 'Restored proper exponential backoff spacing between retry attempts');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('65992978-4a26-49eb-9bd8-d8b3bb17f000', '75a847e3-24d6-5a0a-8e38-c7b5ee6cf85e', 2, 'Scaled up the fulfillment-worker deployment', 'kubectl scale deployment fulfillment-worker --replicas=12', 'Consumption rate exceeded arrival rate; queue depth began draining');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('6852554f-127a-4160-ae34-75050286ba53', 'aac040e7-1280-5f79-871d-dc07c9f66450', 1, 'Checked the certificate expiry against the checkout-api ingress endpoint', 'openssl s_client -connect checkout-api.internal:443 -servername checkout-api.internal | openssl x509 -noout -dates', 'Confirmed notAfter was in the past');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('6b7e172b-e5c8-476d-9f69-7d2e5b4a4e01', 'f87837a4-b610-59b0-9abe-99c8f98957c9', 1, 'Checked config.loaded log values against documented defaults', 'grep ''config.loaded'' checkout-handler.log', 'Found PAYMENT_BASE_DELAY_SECONDS=0.05 instead of the intended 0.5');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('6ebb78eb-c465-4bcb-8a49-ef634b5ce7e4', '25dd5cb5-0180-533e-bc8f-98c43739bd11', 2, 'Restarted the fulfillment-worker deployment', 'kubectl rollout restart deployment fulfillment-worker', 'Pods came back healthy; queue began draining immediately');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('705d7ad8-599f-47dc-a59f-31cda64879e0', '75a847e3-24d6-5a0a-8e38-c7b5ee6cf85e', 3, 'Temporarily raised QUEUE_MAX_DEPTH to give fulfillment-worker headroom to catch up', 'edit config.py: QUEUE_MAX_DEPTH = 8000', 'No further checkout.enqueue_failed errors for the remainder of the promo window');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('72cf1b42-ca58-4708-ba10-3f568de5cbcc', 'c11c7f5a-4b80-5f45-9b3f-44f964538431', 1, 'Correlated the geographic distribution of checkout.payment_failed against availability zone', NULL, 'Found impact was isolated to a single AZ, not global — pointed away from a provider-wide outage');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('793ab96c-7970-46d0-8ce7-fb1ceb2c74c8', '25dd5cb5-0180-533e-bc8f-98c43739bd11', 4, 'Added a fulfillment-worker liveness alert independent of the queue-depth alert', NULL, 'Catches future consumer outages before the queue has a chance to fill');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('7d245287-cf8d-452b-b07e-2c8d8f4aabea', 'c11c7f5a-4b80-5f45-9b3f-44f964538431', 2, 'Asked the network team to review recent firewall/ACL changes affecting that AZ', NULL, 'Identified an ACL change from the previous day restricting egress to the payment-gateway provider');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('81c6a28a-6db9-4758-bdf9-c7afc129a199', '1e7223d6-7b55-55a2-b7c5-e78d58d2278e', 1, 'Confirmed provider-side outage via the gateway status page and correlated GatewayTimeout errors in PaymentClient._call_gateway', NULL, 'Root cause identified as an upstream provider issue, not an application bug');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('831b4e20-bd0a-4395-b8e8-b5ab465c841e', '98d7bf23-3028-57e9-b69f-5cde02b070e8', 2, 'Spot-checked api.request and api.error logs for the affected time range', 'grep ''api.error'' checkout-api.log', 'No elevated error rate or unusual err= values found');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('8e6d419c-1651-46d8-b283-8723455b63c1', '5a77bbb3-8a19-52f7-84b5-1fb021b02085', 1, 'Checked crashed pod logs for the startup failure', 'kubectl logs deployment/checkout-handler --previous', 'Found a Python ImportError in checkout.py at process startup');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('8ed4adb1-107e-444b-b7fd-3f8a29946c62', 'b6760c17-f4ba-5516-a3e3-d5f9738c04e2', 2, 'Reverted the offending deploy', 'git revert <deploy-commit> && kubectl rollout restart deployment checkout-handler', 'PAYMENT_MAX_RETRIES restored to 8; checkout.payment_failed rate returned to baseline within minutes');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('967a5c20-2a78-4737-b966-1d7f25934f91', '25dd5cb5-0180-533e-bc8f-98c43739bd11', 1, 'Checked fulfillment-worker pod status', 'kubectl get pods -l app=fulfillment-worker', 'Found 0/5 pods Ready');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('a37763c2-f9d5-4260-bed2-20bfab7e1df8', '7c0ceb99-d72d-5f20-8c1f-2138b71a4a47', 3, 'Increased the application connection pool size as a stopgap', 'edit config.py: DB_POOL_SIZE = 20', 'Reduced frequency of db.pool.exhausted during the remainder of the spike, but did not eliminate it under sustained peak load');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('a7d17e35-2dc8-4c49-aa69-256ea9d3dd2b', '1e7223d6-7b55-55a2-b7c5-e78d58d2278e', 3, 'Monitored payment.retry and payment.exhausted rates until the provider recovered', NULL, 'payment.retry volume dropped back to baseline once the provider status page confirmed resolution');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('a86559fe-f496-41ed-bf3f-cd480db2bc11', 'c11c7f5a-4b80-5f45-9b3f-44f964538431', 3, 'Network team reverted the ACL change', NULL, 'GatewayTimeout rate in the affected AZ returned to baseline within minutes');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('ad0408ee-37d3-4834-bd73-cbecbf7e2520', '3d877d0d-f7de-5aea-83d0-e2a637c109b0', 1, 'Correlated 502 timestamps against pod readiness transition events', 'kubectl get events --field-selector reason=Unhealthy', 'Found readiness probe flapping coincided exactly with the 502 trickle, not application errors');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('c4658801-25d2-4a41-8741-21747f2b9520', '97b04640-5582-5d21-ae45-d1b15bf32b5a', 3, 'Backfilled a retroactive review of the missed window', NULL, 'Confirmed the underlying payment issue had self-resolved and no further remediation was needed for that specific occurrence');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('c5953bf0-e83f-4053-962c-97ee00cba48c', '97b04640-5582-5d21-ae45-d1b15bf32b5a', 1, 'Reviewed historical checkout.payment_failed rate distribution to pick a realistic alert threshold', NULL, 'Determined the existing threshold was roughly 10x higher than any real moderate incident would reach');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('c5963eb3-10ed-4ea2-bed1-1c66c2f71eaa', '97b04640-5582-5d21-ae45-d1b15bf32b5a', 2, 'Lowered the alert threshold and added an intermediate warning-level tier', NULL, 'Future incidents of this scale will page on-call instead of requiring manual dashboard discovery');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('cf3bf9fc-3d95-454d-97db-3ee2c06dc369', '75a847e3-24d6-5a0a-8e38-c7b5ee6cf85e', 1, 'Checked FulfillmentQueue.depth() trend leading up to the incident', NULL, 'Confirmed a steady climb to max over ~40 minutes, not a sudden spike — consistent with a capacity mismatch rather than a burst');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('d1c62c53-eab1-406d-8101-19b89b903920', '7c0ceb99-d72d-5f20-8c1f-2138b71a4a47', 4, 'Enabled request-level load shedding at checkout-api during peak windows', 'kubectl apply -f checkout-api-ratelimit.yaml', 'Reduced customer-visible failure rate by rejecting excess requests early instead of failing deep in checkout-handler');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('d706522e-dc6d-415c-b2a7-f024aace90e9', '98d7bf23-3028-57e9-b69f-5cde02b070e8', 4, 'Requested specific order_ids or timestamps from support to trace individual checkout.start/checkout.success pairs', NULL, 'No usable order_ids were provided before the reporting customers churned off the topic');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('de68a774-2a86-4b3a-ae2f-ca5a79554f7b', 'ca2f2071-518a-5310-ad5d-329dca7fc23a', 2, 'Reverted the logging level and cleared accumulated log files', 'kubectl set env deployment/checkout-handler LOG_LEVEL=INFO', 'Disk usage dropped sharply; pods stopped being evicted');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('de715bdb-bcf6-42ca-833e-12fdf25fd8d1', '5a77bbb3-8a19-52f7-84b5-1fb021b02085', 3, 'Fixed the import in a follow-up PR and added a container smoke-test that imports all application modules during the build', NULL, 'Prevents future broken-import deploys from reaching production');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('e553a092-ff2a-4d7e-8e83-b8ad10923030', '75a847e3-24d6-5a0a-8e38-c7b5ee6cf85e', 4, 'Reverted QUEUE_MAX_DEPTH to 5000 after the promo window closed and added a pre-promo fulfillment-worker scaling step to the promo runbook', 'edit config.py: QUEUE_MAX_DEPTH = 5000', 'Queue depth returned to normal baseline; future promos scale fulfillment-worker proactively');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('e66461fb-da0b-4e4e-a165-ca3728e6b3f0', '845e68dd-ab1c-527b-a154-a48e5dbb392c', 3, 'Added a CI smoke-test assertion on the config.loaded pool_size value before deploys are allowed to promote', NULL, 'Catches config typos of this kind before they reach production');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('ea60580d-533a-46e2-a350-2bcf76901917', 'f87837a4-b610-59b0-9abe-99c8f98957c9', 3, 'Redeployed checkout-handler with the corrected config', 'kubectl rollout restart deployment checkout-handler', 'Retry volume against the gateway dropped to levels appropriate for the blip''s actual severity');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('eb5a40e5-76a7-4497-98ae-a69fd62d0520', '3d877d0d-f7de-5aea-83d0-e2a637c109b0', 2, 'Increased the readiness probe timeout and failure threshold', 'kubectl patch deployment checkout-api --type=json -p ''[{"op":"replace","path":"/spec/template/spec/containers/0/readinessProbe/timeoutSeconds","value":5}]''', 'Readiness flapping stopped and the 502 trickle disappeared');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('f0ba6c36-dbe3-4169-8f2c-a83a7d720003', 'c11c7f5a-4b80-5f45-9b3f-44f964538431', 4, 'Added a synthetic health check exercising payment-gateway connectivity from each AZ', NULL, 'Catches future per-AZ connectivity regressions before they affect customer checkouts');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('f55e642f-93a7-4d8d-9cf4-43fa95e16fdb', '7c0ceb99-d72d-5f20-8c1f-2138b71a4a47', 5, 'Filed a follow-up ticket to investigate why pool exhaustion still occurs at the new, larger pool size under peak load', NULL, 'Incident closed as mitigated; follow-up investigation was never completed and the underlying cause remains undetermined');
INSERT INTO resolution_steps (id, incident_id, step_order, action, command, outcome) VALUES ('fc7fa2b9-0f6f-4f8b-ae70-2fdf863fe68e', 'aac040e7-1280-5f79-871d-dc07c9f66450', 2, 'Manually issued and deployed a new certificate', 'ccloud cert issue --service checkout-api && kubectl apply -f checkout-api-tls-secret.yaml', 'TLS handshake errors stopped immediately after rollout');

-- doc_chunks: 15 rows
INSERT INTO doc_chunks (id, project, doc_title, heading, body, doc_type, source_path, created_at, embedding) VALUES ('0a1d099d-2cfd-5809-b13e-491e117a3239', 'sample', 'Checkout Service Runbook', 'General incident response checklist', 'For any checkout_service alert: (1) identify which signal fired using the canonical log lines in Setup & Operations; (2) start at checkout-handler, since it is the hub through which every downstream failure (connection-pool, payment-gateway, fulfillment-queue) surfaces — see Architecture; (3) check the code_changes log for anything merged in the last two weeks touching the affected file (config.py, metrics.py, db.py, payment_gateway.py, fulfillment_queue.py) — many incidents trace back to a recent, innocuous-looking merge rather than a sudden environmental change; (4) if logs and recent changes don''t explain the symptom, and the dashboards look inconsistent with customer reports, treat that mismatch itself as a signal — verify what a given metric is actually measuring (e.g. its aggregation) before trusting it; (5) escalate to a code-level review of checkout-handler''s interaction with the affected component if standard mitigations (scaling, restarting, config rollback) don''t resolve the symptom.', 'runbook', 'docs/runbook.md', '2026-08-19 13:42:19.868616+00:00', '[-0.029729268,-0.010879275,-0.0278008,0.043071292,-0.022369178,-0.025805788,-0.00314322,-0.023473073,0.041528746,0.071298234,-0.030518258,0.01940783,0.019497816,-0.00512173,-0.0804694,-0.011758565,-0.03257469,-0.0031684118,-0.04689186,0.011396755,0.013863998,-0.015136394,-0.06371729,-0.015382876,-0.066024914,0.037033364,-0.003835517,-0.074409656,0.0799166,0.038824655,-0.0528207,-0.04103829,-0.0011236694,-0.035040557,-0.007359623,-0.028265417,0.022968385,-0.03801772,-0.048687175,-0.051888604,-0.06788361,0.021976804,0.043441337,-0.0667384,-0.06643512,0.013176794,-0.029502923,-0.003096486,0.029305896,-0.03128711,-0.02123091,0.04510704,0.0041060587,-0.034189697,-0.0055492083,-0.