INSERT INTO doc_chunks (id, project, doc_title, heading, body, doc_type, source_path, created_at, embedding) VALUES ('20133ac7-eb89-54ad-b049-992226d0d854', 'sample', 'Checkout Service Architecture', 'Overview', 'checkout_service is a small Python payment/checkout service. It has no complex business logic by design; its job is to accept a checkout request, charge the customer through an external payment gateway, and hand the order off to fulfillment. The service is composed of a handful of modules under sample_project/checkout_service/: api.py, checkout.py, db.py, payment_gateway.py, fulfillment_queue.py, config.py, and metrics.py. In incident and dashboard tooling these map to the logical components checkout-api, checkout-handler, connection-pool, payment-gateway, and fulfillment-queue.', 'architecture', 'docs/architecture.md', '2026-08-19 13:42:19.118754+00:00', '[-0.008304053,-0.005634338,-0.03988865,0.005903992,-0.020896409,-0.013509702,0.017012198,0.004447275,0.019023681,0.06972937,0.012243214,-0.009921754,0.03167614,0.015900036,-0.084249385,0.025346689,-0.02848349,-0.02687789,-0.056684576,-0.016264586,-0.016409064,-0.014275976,-0.039645996,0.0046184664,-0.067698434,0.06937398,-0.011313668,-0.007849459,0.0747327,0.020274956,-0.06056991,-0.009750362,0.0023674462,-0.06296286,0.012163261,-0.00054583506,0.027600823,-0.05773996,-0.04283288,-0.037740663,0.010592723,0.028055143,0.018379994,-0.03755764,-0.059812322,0.010215597,0.012994378,-0.04090827,0.009563105,-0.03752156,-0.010328933,0.04413855,-0.005724722,-0.0206818,-0.057405837,-0.020175263,0.0033153768,0.0023006953,-0.019557985,-0.01932499,-0.0072594336,-0.0005901956,0.022956701,-0.048442926,0.007733886,0.036458965,-0.076355025,-0.019922825,0.0010081581,0.00019315083,-0.0076182154,0.0230532,-0.028416187,-0.04051368,-0.040980566,0.015366566,-0.01729644,-0.019897819,0.012921911,0.04309521,0.05869538,0.013934353,-0.0031315691,-0.021929923,-0.0061718426,-0.018141752,0.015603174,-0.01018554,0.003778932,-0.00532344,0.