INSERT INTO doc_chunks (id, project, doc_title, heading, body, doc_type, source_path, created_at, embedding) VALUES ('2a116dd3-c4e9-5fcb-a272-285c46133a8e', 'sample', 'Checkout Service Runbook', 'Signal: payment.retry / payment.exhausted (payment gateway issues)', 'Symptom: a rising rate of payment.retry order_id=... attempt=.../... backoff=...s events, sometimes culminating in payment.exhausted order_id=... attempts=... and checkout.payment_failed. This indicates payment-gateway is slow or intermittently failing. First-line response: (1) check the external payment processor''s own status page and latency metrics; (2) check PAYMENT_GATEWAY_TIMEOUT_SECONDS (default 30) and confirm PaymentClient._call_gateway is timing out at the expected threshold rather than hanging; (3) review PAYMENT_MAX_RETRIES (default 8) and PAYMENT_BASE_DELAY_SECONDS (default 0.5) — a recent increase to either will make retry storms longer and more visible; check code_changes for recent edits to config.py before assuming these are still at defaults; (4) if the gateway is confirmed degraded, consider reducing PAYMENT_MAX_RETRIES temporarily to fail faster rather than pile up retries.', 'runbook', 'docs/runbook.md', '2026-08-19 13:42:19.758829+00:00', '[-0.004491696,-0.002406538,-0.05669796,0.08172018,-0.007137187,-0.036923517,0.029136097,-0.04233449,0.03293498,0.072165206,-0.017821044,0.039924517,0.0099967625,-0.030596772,-0.0491007,-0.0053776936,-0.004454626,-0.05115542,-0.04691618,-0.011455096,-0.013924869,-0.012521621,-0.021186754,0.02331371,-0.038699463,0.039377876,-0.005244309,-0.029025542,0.055849165,0.028043939,-0.029798882,-0.023346445,0.0016195893,-0.02836465,-0.025697198,-0.0037282195,0.016027413,-0.05689285,-0.028329404,-0.082326464,0.0017278405,-0.0017120966,0.0022748474,-0.035472747,-0.031021966,-0.029016031,-0.028906,-0.027514353,0.020618878,-0.02955212,-0.030716455,0.010256861,-0.034940366,-0.0049335426,-0.033144128,-0.0066883448,0.01501699,0.0039487467,-0.036371946,-0.03577917,0