INSERT INTO doc_chunks (id, project, doc_title, heading, body, doc_type, source_path, created_at, embedding) VALUES ('2f5124f4-ed28-59f3-a78e-1660ab695a28', 'sample', 'Checkout Service Setup & Operations', 'Metrics and dashboards', 'MetricsEmitter (metrics.py) is the single place that emits latency and count metrics for the service, via MetricsEmitter.emit_latency(name, value_ms) and MetricsEmitter.emit_count(...), both reachable through the process singleton get_emitter(). Every latency emission is also logged as metrics.latency name=... value_ms=... agg=..., where agg reflects the configured LATENCY_AGGREGATION for that metric. Checkout latency dashboards and SLO alerts are built directly on top of this aggregation, so the choice of aggregation function determines what kind of regression the dashboard can actually detect — an aggregation that smooths over the tail of the distribution will not flag a regression that only affects a minority of slow requests. Always confirm what LATENCY_AGGREGATION is currently set to, and check recent code_changes for edits to metrics.py, before trusting a green latency dashboard during a customer-reported slowness complaint.', 'setup', 'docs/setup.md', '2026-08-19 13:42:19.645592+00:00', '[-0.02403591,-0.0030460418,-0.040449433,0.06779931,0.00080438255,0.0025635168,-0.0034380197,-0.013696132,0.047687367,0.062903814,-0.080295816,-0.011733633,-0.015933078,-0.00092758914,-0.05325497,-0.017503355,0.008845803,-0.023128077,-0.061683804,0.010330252,0.0343459,0.0045348727,-0.030905623,-0.031945474,-0.023678252,0.004934477,-0.018525312,0.016919613,0.066312894,0.022197682,-0.005509112,-0.046514414,-0.016577624,-0.089913726,0.044412985,-0.038049895,-0.018805604,0.00019212299,-0.012328464,-0.064618684,0.034766637,-0.00088805635,0.0044837017,-0.024534786,-0.058979053,-0.026311006,-0.012822425,-0.016740885,0.031923387,-0.04215353,0.014208872,0.021808457,0.012867061,-0.010434059,0.008014972,-0.018090805,-0.0013425248,0.029525464,-0.0025742718,0.0