INSERT INTO doc_chunks (id, project, doc_title, heading, body, doc_type, source_path, created_at, embedding) VALUES ('651fb186-b028-5c35-a2ea-b5580a33ae31', 'sample', 'Checkout Service Runbook', 'Signal: fulfillment.queue.full (queue saturation)', 'Symptom: fulfillment.queue.full depth=... max=... events, with checkout.enqueue_failed following as FulfillmentQueue.enqueue raises QueueFull once depth reaches QUEUE_MAX_DEPTH (default 5000). This means fulfillment-worker (the downstream consumer, external to this service) is draining the queue slower than checkout-handler is filling it. First-line response: (1) check fulfillment-worker''s own health and throughput — this is very often a downstream consumer problem rather than a checkout_service bug; (2) use FulfillmentQueue.depth() / the fulfillment.enqueued depth=... log trend to see how fast depth is climbing; (3) if fulfillment-worker cannot be fixed quickly, consider pausing or rate-limiting checkout traffic upstream to let the queue drain; (4) do not raise QUEUE_MAX_DEPTH as a first response — it only delays the failure and increases the backlog fulfillment-worker has to clear.', 'runbook', 'docs/runbook.md', '2026-08-19 13:42:19.812128+00:00', '[0.004813523,0.00020136272,-0.029544942,0.06528297,-0.036346734,-0.015797552,0.044503137,0.01485517,0.033980947,0.099027656,-0.035583083,0.018706597,0.021207193,0.005706477,-0.051483374,-0.019171469,-0.016382357,-0.040674783,-0.058755226,-0.005394196,-0.008898314,-0.0040554777,-0.056163073,0.0034797972,-0.037758112,0.052655455,0.004892486,-0.021674942,0.053776074,0.054771315,-0.032725614,0.0040758736,0.0010151537,-0.051051825,0.0049420632,0.012172967,0.0042485595,-0.009652374,-0.031393055,-0.07966257,0.010464597,-0.00911928,0.009058099,-0.062047187,-0.029454233,-0.0111365765,0.013701078,0.005392396,0.011251557,-0.0171619,-0.029791404,0.012001995,-0.001375941,-0.052103944,0.022700543,-0.01348756,0.021153087,-0.018805495,0.005360341,-0.008849987,0.027187575,0.008773948,0.0253