INSERT INTO doc_chunks (id, project, doc_title, heading, body, doc_type, source_path, created_at, embedding) VALUES ('83a5860a-790b-5517-9205-a02370f9b34b', 'sample', 'Checkout Service Architecture', 'checkout-handler is the hub', 'checkout-handler (CheckoutHandler.process) is the hub of the request graph: it is the only component that talks directly to connection-pool, payment-gateway, and fulfillment-queue. This has an important operational consequence: problems that originate in any one of those three downstream components will surface as errors or latency inside checkout-handler, and from there propagate up to checkout-api. When triaging a checkout-api alert, always check checkout-handler''s logs first, then walk outward to the connection pool, the payment gateway, and the fulfillment queue.', 'architecture', 'docs/architecture.md', '2026-08-19 13:42:19.220912+00:00', '[-0.016634772,0.0054461733,-0.055591553,0.010296025,-0.031089535,-0.0060034096,0.018496327,-0.0262708,0.061027274,0.043849867,-0.016165001,0.02438825,-0.010979004,-0.005241431,-0.077675715,-0.0072479686,-0.015036511,-0.007093715,-0.058946628,-0.0105578685,0.0023804405,-0.034905154,-0.04666367,-0.023745669,-0.046591837,0.045523036,-0.01434447,-0.014471829,0.076039754,0.014372946,-0.07260551,-0.003856754,0.016098132,-0.024093386,0.012807927,-0.0033984352,0.011470701,-0.016307533,-0.02903347,-0.049242627,-0.03664812,-0.0009519996,0.03094744,-0.048966646,-0.0622735,-0.00064613076,-0.011186197,-0.055246424,0.011328884,-0.056573283,-0.025608553,0.02679942,-0.0029197747,0.0057218364,-0.018958852,-0.016661212,0.016601844,-0.03349576,-0.00022398704,-0.008432917,0.012551161,-0.023915611,0.00910788,-0.05341808,0.000320556,0.008218843,-0.054659247,-0.040749073,0.0074781687,0.012265563,-0.07542459,0.03034448,0.0042991517,-0.03481198,-0.001810857,0.021989083,-0.018924626,-0.0074449787,-0.010276566,-0.014726647,0.028788276,0.021758588,0.008672393,-0.040796515,-0.01775782,-0.011128697,-0.004610608,0.018916763,0.0