INSERT INTO doc_chunks (id, project, doc_title, heading, body, doc_type, source_path, created_at, embedding) VALUES ('a27cb20f-1bc4-54b8-9419-9538927d2968', 'sample', 'Checkout Service Setup & Operations', 'Changing configuration safely', 'Config values are read once at startup by load(), so any change to config.py requires a redeploy to take effect; there is no hot-reload. Because PAYMENT_MAX_RETRIES and PAYMENT_BASE_DELAY_SECONDS jointly determine how long a single charge() call can run in the worst case, treat changes to either as a latency-affecting change, not just a reliability tweak — raising retries or backoff makes individual checkout requests take longer end-to-end, which has knock-on effects for anything holding resources for the duration of the call. Always check the recent code_changes log for edits to config.py before assuming current defaults are still in effect.', 'setup', 'docs/setup.md', '2026-08-19 13:42:19.480189+00:00', '[-0.006727483,0.0068175783,-0.050853647,0.04677756,-0.033528075,-0.045432355,0.0031815728,-0.029022528,-0.00025751584,0.052632824,0.04509455,0.03540824,0.060380798,-0.030326515,-0.034533765,-0.023635244,-0.021167884,-0.0012740962,-0.03378298,0.018929517,-0.020848071,-0.031573147,-0.04077297,0.015799526,-0.0422244,0.0602943,-0.027631242,-0.019782813,0.08175054,0.05646088,-0.010857284,-0.019870743,0.014452442,-0.0093161315,-0.011205304,-0.017658073,0.0041927346,-0.03416974,-0.04308397,-0.074127845,0.018070815,-0.010880172,0.006985761,-0.020043364,-0.060014617,-0.010280399,-0.04067647,0.005887989,-0.0016982387,-0.041099444,0.006216043,0.029785533,-0.018190945,-0.0017799765,-0.057882205,0.0018093754,0.0043796725,-0.02834303,-0.008027442,0.012323522,0.02269041,-0.026857544,0.013935443,-0.03460043,0.041044187,0.033169046,-0.0118353255,0.001709354,-0.002073818,0.027456665,0.004512385,0.034025118,0.016713694,-0.042982113,0.016779674,0.018998729,-0.006926951,-0.025667503,-0.01731242,0.020710366,-0.00788982,0.010362844,0.008522522,-0.0498