INSERT INTO doc_chunks (id, project, doc_title, heading, body, doc_type, source_path, created_at, embedding) VALUES ('a42cbe58-b277-53bf-b840-f6f626ab71af', 'sample', 'Checkout Service Architecture', 'Request flow', 'A checkout request enters through CheckoutAPI.post_checkout (api.py), which delegates immediately to CheckoutHandler.process (checkout.py). CheckoutHandler.process is the orchestration point for a single order: it acquires a database connection from the connection pool, charges the customer through the payment gateway, and enqueues the order for fulfillment. CheckoutAPI.get_health is a separate, lightweight endpoint used for liveness/readiness checks and does not touch the payment or queue paths. Every checkout is logged with checkout.start order_id=... amount=..., and ends in either checkout.success order_id=... or an error event such as checkout.payment_failed or checkout.enqueue_failed.', 'architecture', 'docs/architecture.md', '2026-08-19 13:42:19.175937+00:00', '[-0.02554176,-0.0058138142,-0.07998926,0.025410801,-0.047297835,-0.015811522,0.009708949,0.026636241,0.046456393,0.06359847,-0.00085880625,0.0023551558,0.007924809,0.019500757,-0.06366605,0.02482701,-0.045921713,-0.024290072,-0.022360913,-0.012105392,0.0013198298,-0.03821154,-0.05278352,0.00011992365,-0.047475647,0.051064186,-0.0007886935,-0.018220011,0.078792065,0.018418815,-0.054401323,0.015319228,0.010699485,-0.033169463,0.030234143,-0.015227746,-0.0018053993,-0.06419718,-0.029211933,-0.037952825,0.016848315,0.010533099,0.017703684,-0.017799346,-0.10186817,-0.006936747,-0.019148758,-0.023591237,0.026170354,-0.034407206,-0.011994596,0.023123937,0.0011620357,-0.009657046,-0.047054533,-0.009259959,-0.011879577,-0.013832021,-0.0070675695,-0.004967256,-0.010972273,-0.036510944,0.042628508,-0.054004114,-0.016143575,0.02166163,-0.041486178,-0.02025027,0.0026963244,0.0059755403,-0.042166065,-0.0048421803,-0.033161987,-0.040318802,0.002304442,0.029706117,-0.0010883412,-0.042328425,-0.010422686,0.