INSERT INTO doc_chunks (id, project, doc_title, heading, body, doc_type, source_path, created_at, embedding) VALUES ('a80654a0-ab8a-59cb-bb84-d418493527b5', 'sample', 'Checkout Service Architecture', 'Components: payment-gateway', 'payment-gateway (payment_gateway.py) wraps the external payment processor behind PaymentClient.charge(order_id, amount), which internally calls PaymentClient._call_gateway(...). If the gateway is slow or unavailable, charge() retries with exponential backoff, logging payment.retry order_id=... attempt=.../... backoff=...s on each attempt. If every retry is exhausted the call gives up and logs payment.exhausted order_id=... attempts=..., which CheckoutHandler.process surfaces as checkout.payment_failed. Retry behavior is governed by the PAYMENT_MAX_RETRIES and PAYMENT_BASE_DELAY_SECONDS config values described in Setup & Operations.', 'architecture', 'docs/architecture.md', '2026-08-19 13:42:19.312831+00:00', '[-0.020988932,0.008081843,-0.06399405,0.03878941,-0.02586116,-0.02371048,-0.003330286,-0.049926583,0.020636898,0.052290384,-0.024767091,0.041883856,0.00028727014,-0.007437195,-0.06208317,0.028043086,-0.044078097,-0.061485328,-0.040500324,0.019871758,-0.03173784,-0.04032337,-0.023183433,0.007860287,-0.04074419,0.03637304,-0.013898978,-0.031651627,0.06151028,0.0032010498,-0.020687632,-0.0036457167,-0.0056681912,-0.033617936,0.009644977,-0.010648251,0.01789821,-0.06594837,-0.013772719,-0.054821357,0.013551483,0.011908865,0.0057188,-0.030011466,-0.057864457,-0.013412544,0.0048420248,-0.022028347,0.0074799345,-0.032746993,-0.02603812,0.018716747,-0.025144428,-0.0008965343,-0.052177355,-0.027688248,0.015224434,-0.013472334,-0.036366746,0.0042740977,0.00489539,-0.018588122,0.027233662,-0.060350128,0.027141215,0.008116139,-0.017924916,-0.005168792,-0.017688949,-0.0003550117,-0.014751486,0.038049687,0.01647383,-0.025923641,-0.0075476607,0.033492867,-0.008991291,-0.029832825,0.018727982,0.012891053,0.03725856,0.053786997,-0.011340796,-0.021158