INSERT INTO doc_chunks (id, project, doc_title, heading, body, doc_type, source_path, created_at, embedding) VALUES ('aba21012-d6f1-53b9-8e23-3a19bf98cde4', 'sample', 'Checkout Service Setup & Operations', 'Deploying the service', 'checkout_service is deployed as a single process exposing CheckoutAPI. On startup, config.load() runs first and emits config.loaded pool_size=... payment_max_retries=..., followed by initialization of get_pool(), get_queue(), and get_emitter(). Use CheckoutAPI.get_health(request) as the liveness/readiness probe target — a healthy response does not by itself guarantee the connection pool or payment gateway are healthy, only that the process is up and able to handle requests. After any deploy, watch for an immediate spike in db.pool.exhausted, payment.retry, or fulfillment.queue.full events, which usually indicate a config regression rather than a traffic change.', 'setup', 'docs/setup.md', '2026-08-19 13:42:19.529511+00:00', '[-0.01279675,0.00751756,-0.04248808,0.035744905,-0.046701036,-0.022987979,-0.008736863,0.010642953,0.028276497,0.026377225,0.0064769266,0.007885069,0.03741311,0.012184472,-0.075856656,0.013392559,-0.0454375,0.00032526127,-0.054452576,-0.008943692,-0.02568627,-0.015694914,-0.022612907,0.023591056,-0.04944458,0.071282536,-0.026020199,-0.03014024,0.09634776,0.025976324,-0.03992381,-0.007337532,0.020424353,-0.019057985,-0.0039526783,-0.014713823,0.019101998,-0.05023353,-0.04834506,-0.04922427,-0.00225932,0.014554739,0.02786503,-0.018263003,-0.056640796,0.011538124,-0.012119404,-0.025263194,0.007938378,-0.024174169,-0.027307138,0.050192192,-0.006363657,-0.01829173,-0.0406051,-0.02773872,-0.017601162,0.010532162,-0.01751732,0.007488533,0.013364383,-0.012784558,0.014734827,-0.037898872,0.025559647,0.054075222,-0.016028883,-0.02190117,0.019886361,0.014098341,-0.03284297,0.053123858,-0.04126129,-0.05533187,0.0030975891,0.031573184,-0.0072767404,-0.02687646,-6.8750255e-06,0.016649332,0.014374899,0.004610928,0.032238685,-0.03396