INSERT INTO doc_chunks (id, project, doc_title, heading, body, doc_type, source_path, created_at, embedding) VALUES ('cc4bfeee-051a-5a44-88d3-2002c909f164', 'sample', 'Checkout Service Runbook', 'Signal: db.pool.exhausted (connection pool exhaustion)', 'Symptom: checkout requests fail with ConnectionPoolExhausted, and logs show db.pool.exhausted in_use=... size=... with in_use at or near DB_POOL_SIZE (default 10). This usually surfaces during traffic spikes. First-line response: (1) confirm current pool utilization by tailing db.pool.acquire / db.pool.release counts; (2) check whether the underlying database itself is healthy and responsive — rule out a real DB-side capacity or connectivity problem first; (3) as a mitigation, consider temporarily raising DB_POOL_SIZE and redeploying, which buys headroom while you keep investigating; (4) check payment-gateway health and latency (payment.retry / payment.exhausted volume) since slow downstream calls can cause connections to be held longer than usual. Note: raising DB_POOL_SIZE or scaling the database does not always resolve this — if the pool keeps draining at the same rate after a capacity increase, escalate for a deeper code-level investigation into how long checkout-handler holds each connection.', 'runbook', 'docs/runbook.md', '2026-08-19 13:42:19.698953+00:00', '[-0.012808389,0.015229791,-0.016437868,0.06040125,-0.021716021,-0.022755455,0.05038893,-0.021420423,0.025145333,0.052985113,0.021262316,0.022890024,0.018432803,-0.018682763,-0.036398098,0.02498199,0.004264437,-0.04186313,-0.060302805,0.0045226887,-0.0016244656,-0.013593298,-0.010020542,0.020182151,-0.03197604,0.04840173,-0.022952773,-0.031020999,0.06692435,0.033052787,-0.043494076,-0.01410972,0.0036548078,-0.016923135,-1.519552e-05,-0.005195649,0.0060512633,-0.036499258,-0.01739158,-0.06187387,-0.019314662,-0.0038874212,0.025752177,-0.043954886,-0.013662671,0.0038667058,-0.013115169,-0.0340345,0.027533015,-0.03924363,-0.041705865,0.03074544,-0.036290832,-0