INSERT INTO doc_chunks (id, project, doc_title, heading, body, doc_type, source_path, created_at, embedding) VALUES ('e868485f-577b-539f-9ade-b5720ff28995', 'sample', 'Checkout Service Architecture', 'Components: connection-pool', 'connection-pool (db.py) manages a fixed-size pool of database connections via ConnectionPool.acquire() and ConnectionPool.release(), with the underlying handle represented by _Connection. Pool size is fixed at process start (see DB_POOL_SIZE in Setup & Operations). When every connection is checked out, the next caller to ConnectionPool.acquire() raises ConnectionPoolExhausted and the service logs db.pool.exhausted in_use=... size=.... get_pool() returns the process-wide singleton pool instance.', 'architecture', 'docs/architecture.md', '2026-08-19 13:42:19.263663+00:00', '[-0.004483675,-0.00077186077,-0.030153876,0.010235185,-0.026526297,0.009522438,0.01764968,-0.030648435,-0.0039203395,0.03773976,0.011061887,0.0038670085,0.022559097,0.0067629064,-0.028488677,0.045592137,-0.03034655,-0.050152525,-0.064910725,-0.018441904,0.012190563,0.040619314,-0.020328585,-0.012447079,-0.033646755,0.049528804,-0.02398495,-0.0055419113,0.07815291,0.017970758,-0.07058964,-0.0061855195,-0.021685697,-0.0182075,0.01875488,0.004677933,0.004434055,-0.013466574,-0.043027386,-0.033680182,0.017716514,-0.0051398827,0.045417503,-0.023380635,-0.067398265,0.0058248197,-0.017139513,0.01140637,0.022201909,-0.040863335,-0.020843463,0.052362997,-0.013073456,-0.0014948505,-0.019714508,-0.020500742,-0.048943266,0.033245772,-0.011638816,0.021618353,-0.031900667,-0.036325507,-0.00055853947,-0.06014371,0.017374856,0.055662632,0.0023896252,-0.019461978,0.035127275,-0.035932716,-0.023213895,0.024489895,-0.04650207,-0.073292196,0.0096359,0.051732846,0.0074355174,-0.010701103,-0.01837673,0.016985966,0.034628462,0.04264409,0.020988096,-0.025096867,0.001771992,-0.051082358,0.016582435,-0.007016882,-0.033461932,-0.0078678755,-0.0020380775,0.05140801,0.040028322,0.00032126557,0.00520