INSERT INTO doc_chunks (id, project, doc_title, heading, body, doc_type, source_path, created_at, embedding) VALUES ('fb8d5dfc-b772-5515-9b88-0642cbd15f20', 'sample', 'Checkout Service Architecture', 'Components: fulfillment-queue and the fulfillment-worker boundary', 'fulfillment-queue (fulfillment_queue.py) is an in-process bounded queue that CheckoutHandler.process writes to via FulfillmentQueue.enqueue(order_id) once payment has succeeded. FulfillmentQueue.depth() reports current depth, and get_queue() returns the singleton queue. This queue is the hand-off boundary to fulfillment-worker, a downstream consumer that lives outside this repository and drains the queue asynchronously. checkout_service has no visibility into fulfillment-worker internals; from this service''s perspective, fulfillment-worker is a black box that is expected to keep queue depth low. If the queue fills to QUEUE_MAX_DEPTH, enqueue() raises QueueFull and the service logs fulfillment.queue.full depth=... max=....', 'architecture', 'docs/architecture.md', '2026-08-19 13:42:19.362139+00:00', '[-0.0016450282,0.0024151942,-0.06102253,0.03220454,-0.045322355,-0.007690176,0.02790476,0.023990111,-0.0009574921,0.07325679,-0.03842486,0.026591297,-0.0014069142,0.028165739,-0.061716877,-0.007556429,-0.030220846,-0.024811858,-0.06233362,-0.010368459,-0.0038455708,-0.019380573,-0.06384732,-0.016980523,-0.039841,0.066664785,-0.0050438303,0.013551515,0.059208147,0.03815012,-0.05133609,0.018842012,0.021528305,-0.056852352,0.01655541,-0.0019639218,0.0126125915,-0.020719953,-0.014309658,-0.05575205,0.017584154,0.020769957,-0.011851026,-0.037477516,-0.07054197,-0.0073411437,0.017100705,0.016620412,0.016241591,-0.03142285,-0.037198678,0.036365062,0.012280067,-0.043957535,0.011106973,0.00382311,-0.011909567,-0.026372263,0.013025416,0.0091767665,0.0031821174,-0.0044408347,0.02742896,-0.04503875,0.016984686,0.03940929,-0.007956101,-0.022649325,-0.011337004,-0.024372311,0.010042905,0.006311432,-0.037989866,-0.04609