INSERT INTO code_nodes (id, project, name, kind, file, service, source, summary, last_commit, updated_at) VALUES ('2e8ba4d8-b53a-5020-a0d3-8b1d9812193d', 'sample', 'checkout_service.config', 'module', 'sample_project/checkout_service/config.py', 'checkout-service', '"""Configuration for the checkout service.

Central place for tunables. Several of these are the kind of value that gets
changed in a merge and later turns out to be the root cause of an incident.
"""

import logging

log = logging.getLogger("checkout.config")

# Database connection pool. The pool is deliberately small — this matters for
# the connection-exhaustion failure mode (see WORLD.md).
DB_POOL_SIZE = 10
DB_CONNECT_TIMEOUT_SECONDS = 5

# Payment gateway retry behaviour. max_retries was raised from 5 to 8 in an
# earlier merge; combined with the pool-holding bug this is what turns a slow
# gateway into a full outage.
PAYMENT_MAX_RETRIES = 8
PAYMENT_BASE_DELAY_SECONDS = 0.5
PAYMENT_GATEWAY_TIMEOUT_SECONDS = 30

# Fulfillment queue.
QUEUE_MAX_DEPTH = 5000


def load():
    log.info("config.loaded pool_size=%s payment_max_retries=%s", DB_POOL_SIZE, PAYMENT_MAX_RETRIES)
    return {
        "db_pool_size": DB_POOL_SIZE,
        "payment_max_retries": PAYMENT_MAX_RETRIES,
    }
', 'Configuration for the checkout service.', NULL, '2026-08-19 13:41:54.196241+00:00');
INSERT INTO code_nodes (id, project, name, kind, file, service, source, summary, last_commit, updated_at) VALUES ('335c4b13-30b9-57f0-b012-43136efe5d65', 'sample', 'FulfillmentQueue', 'class', 'sample_project/checkout_service/fulfillment_queue.py', 'checkout-service', 'class FulfillmentQueue:
    def __init__(self, max_depth=config.QUEUE_MAX_DEPTH):
        self.max_depth = max_depth
        self._q = deque()

    def enqueue(self, order_id):
        if len(self._q) >= self.max_depth:
            log.error("fulfillment.queue.full depth=%s max=%s", len(self._q), self.max_depth)
            raise QueueFull(f"queue at capacity {self.max_depth}")
        self._q.append(order_id)
        log.info("fulfillment.enqueued order_id=%s depth=%s", order_id, len(self._q))

    def depth(self):
        return len(self._q)', NULL, NULL, '2026-08-19 13:41:54.321447+00:00');
