INSERT INTO code_nodes (id, project, name, kind, file, service, source, summary, last_commit, updated_at) VALUES ('700cfa2d-f869-57a4-b0c4-209ad50eff70', 'sample', 'get_queue', 'function', 'sample_project/checkout_service/fulfillment_queue.py', 'checkout-service', 'def get_queue():
