INSERT INTO code_nodes (id, project, name, kind, file, service, source, summary, last_commit, updated_at) VALUES ('722021c3-b35e-56f5-8949-476764d2a133', 'sample', 'checkout_service.fulfillment_queue', 'module', 'sample_project/checkout_service/fulfillment_queue.py', 'checkout-service', '"""In-memory fulfillment queue.

After a successful charge, the order is enqueued for fulfillment. If the
downstream fulfillment worker stalls, this queue grows without bound up to
QUEUE_MAX_DEPTH, then starts rejecting enqueues.
"""

import logging
from collections import deque

from checkout_service import config

log = logging.getLogger("checkout.fulfillment_queue")


class QueueFull(Exception):
    pass


class FulfillmentQueue:
    def __init__(self, max_depth=config.QUEUE_MAX_DEPTH):
        self.max_depth = max_depth
        self._q = deque()

    def enqueue(self, order_id):
        if len(self._q) >= self.max_depth:
            log.error("fulfillment.queue.full depth=%s max=%s", len(self._q), self.max_depth)
            raise QueueFull(f"queue at capacity {self.max_depth}")
        self._q.append(order_id)
        log.info("fulfillment.enqueued order_id=%s depth=%s", order_id, len(self._q))

    def depth(self):
        return len(self._q)


_QUEUE = FulfillmentQueue()


def get_queue():
    return _QUEUE
', 'In-memory fulfillment queue.', NULL, '2026-08-19 13:41:54.304484+00:00');
INSERT INTO code_nodes (id, project, name, kind, file, service, source, summary, last_commit, updated_at) VALUES ('72c192ef-d59f-5427-a87e-c751464272bb', 'sample', 'checkout_service.api', 'module', 'sample_project/checkout_service/api.py', 'checkout-service', '"""HTTP API surface for the checkout service.

Thin routing layer. Each endpoint delegates to CheckoutHandler. No web
framework — the methods stand in for route handlers so the call graph is clear.
"""

import logging

from checkout_service.checkout import CheckoutHandler, CheckoutError

log = logging.getLogger("checkout.api")


class CheckoutAPI:
    def __init__(self):
        self.handler = CheckoutHandler()

    def post_checkout(self, request):
        """POST /checkout — process a payment for an order."""
        order_id = request.get("order_id")
        amount = request.get("amount")
        log.info("api.request path=/checkout order_id=%s", order_id)
        try:
            result = self.handler.process(order_id, amount)
            return {"status": 200, "body": result}
        except CheckoutError as e:
            log.error("api.error path=/checkout order_id=%s err=%s", order_id, e)
            return {"status": 502, "body": {"error": str(e)}}

    def get_health(self, request):
        """GET /health — liveness probe."""
        log.debug("api.request path=/health")
        return {"status": 200, "body": {"ok": True}}
', 'HTTP API surface for the checkout service.', NULL, '2026-08-19 13:41:54.107562+00:00');
