INSERT INTO code_nodes (id, project, name, kind, file, service, source, summary, last_commit, updated_at) VALUES ('db15c869-f9ba-52ca-b884-4d204fe78cc5', 'sample', 'CheckoutHandler.process', 'function', 'sample_project/checkout_service/checkout.py', 'checkout-service', 'def process(self, order_id, amount):
        log.info("checkout.start order_id=%s amount=%s", order_id, amount)
        pool = db.get_pool()
        conn = pool.acquire()  # connection acquired up front...
        try:
            # ...and held across the (potentially very slow) charge call.
            result = self.payments.charge(order_id, amount)
            self.queue.enqueue(order_id)
            log.info("checkout.success order_id=%s", order_id)
            return result
        except GatewayTimeout as e:
            log.error("checkout.payment_failed order_id=%s err=%s", order_id, e)
            raise CheckoutError("payment failed") from e
        except QueueFull as e:
            log.error("checkout.enqueue_failed order_id=%s err=%s", order_id, e)
            raise CheckoutError("fulfillment unavailable") from e
        finally:
            conn.close()', NULL, NULL, '2026-08-19 13:41:54.188316+00:00');
INSERT INTO code_nodes (id, project, name, kind, file, service, source, summary, last_commit, updated_at) VALUES ('e5a0dcbd-a259-54c2-adf2-b4ec978c2c37', 'sample', 'PaymentClient._call_gateway', 'function', 'sample_project/checkout_service/payment_gateway.py', 'checkout-service', 'def _call_gateway(self, order_id, amount, attempt=0, degraded=False):
