INSERT INTO code_nodes (id, project, name, kind, file, service, source, summary, last_commit, updated_at) VALUES ('f4bbfd29-7670-5793-a95e-e0b9404235a8', 'sample', 'ConnectionPool.acquire', 'function', 'sample_project/checkout_service/db.py', 'checkout-service', 'def acquire(self):
