INSERT INTO code_nodes (id, project, name, kind, file, service, source, summary, last_commit, updated_at) VALUES ('f74fc649-6887-515c-9fbc-17863c20cab3', 'sample', 'FulfillmentQueue.enqueue', 'function', 'sample_project/checkout_service/fulfillment_queue.py', 'checkout-service', 'def enqueue(self, order_id):
