INSERT INTO code_changes (id, project, commit_sha, merged_at, author, title, summary, files_changed, services_affected, affected_components, embedding) VALUES ('133712ea-6d2d-5f7a-adca-b3f85dc4573e', 'sample', 'd4f80a3', '2026-06-05 09:05:00+00:00', 'marcus.lee', 'extract GatewayTimeout as its own exception class', 'Refactored payment_gateway.py so gateway timeouts raise a dedicated GatewayTimeout exception instead of a generic TimeoutError, making it easier for CheckoutHandler.process to distinguish gateway timeouts from other failure modes in its except clauses. Behavior of the retry loop itself is unchanged.', '{"sample_project/checkout_service/payment_gateway.py"}', '{"payment-gateway","checkout-handler"}', '{"GatewayTimeout","PaymentClient.charge","CheckoutHandler.process"}', '[-0.015056827,0.022644723,-0.038685516,0.04296389,-0.014110215,-0.008242111,0.019764533,-0.029102,0.018312408,0.07637273,-0.0241431,0.018552652,0.031820953,-0.02979464,-0.082389586,-0.021585077,-0.016518323,-0.036671966,-0.051867656,0.029284494,0.016246881,-0.025407603,-0.013177016,-0.00032767482,0.0035147634,1.6697764e-05,0.0030626627,-0.040640477,0.058844857,0.027635714,-0.013156958,-0.035016537,-0.025180127,-0.019955087,-0.011479759,-0.015176477,0.023721661,-0.055067126,-0.028382692,-0.03517233,0.018596945,0.002629406,-0.0067126406,-0.054149635,-0.042329103,-0.037909552,-0.0027815655,0.018772043,0.0445149,0.004265795,-0.0030974313,0.015543055,0.0002666018,0.01173206,-0.06854846,-0.037422564,0.007780623,-0.018887743,-0.036594618,-0.016228376,-0.008393874,-0.031020558,0.009036715,-0.05049396,0.010095153,0.029894067,-0.028765276,-0.0061278488,-0.012842552,-0.015910406,-0.026111864,0.030911537,0.0070847278,-0.034647603,-0.007817298,0.031990394,0.02503961,-0.002728362,0.0038171145,0.042846862,-0.021923158,0.032908425,0.008395121,-0.062346768,0.0133672375,-0.038273342,0.007820566,0.03155544,-0.013752724,-0.0125648035,-0.026030006,0.024857998,-0.016972587,-0.03262672,0.025671074,0.013853517,-