-- runbook_steps: 17 rows
INSERT INTO runbook_steps (id, runbook_id, step_order, action, command, outcome) VALUES ('0c9b0b96-099d-407e-a0d0-0a173aa958dc', '2871adfe-4a5c-557d-b7b0-3ed28fe34410', 1, 'Check the fulfillment-worker consumer''s pod status', 'kubectl get pods -l app=fulfillment-worker', '0 Ready pods means a crashed consumer (zero drain); healthy-but-behind means under-scaling');
INSERT INTO runbook_steps (id, runbook_id, step_order, action, command, outcome) VALUES ('0f694383-1900-43e7-b499-64a692912815', 'e6f2db0c-641b-545f-b9b7-db2463920e5e', 3, 'If provider-wide, communicate the outage to support and monitor payment.retry / payment.exhausted until the provider recovers', NULL, 'Reduces duplicate tickets and confirms recovery when payment.retry volume returns to baseline');
INSERT INTO runbook_steps (id, runbook_id, step_order, action, command, outcome) VALUES ('107e8bdf-7722-4e84-92f6-212808e7fac4', '2871adfe-4a5c-557d-b7b0-3ed28fe34410', 2, 'If the consumer is down, restart the fulfillment-worker deployment', 'kubectl rollout restart deployment fulfillment-worker', 'Consumer comes back healthy and the queue begins draining immediately');
INSERT INTO runbook_steps (id, runbook_id, step_order, action, command, outcome) VALUES ('303fdf34-e339-4780-803a-0f175111d1e2', '090c1ad4-40c2-54d0-a0e1-627bf8ae496f', 3, 'Trace the connection''s lifetime in code: CheckoutHandler.process acquires ConnectionPool.acquire() and holds it across PaymentClient.charge()', NULL, 'Confirms the connection is held through PAYMENT_MAX_RETRIES=8 exponential-backoff attempts when the gateway is slow');
INSERT INTO runbook_steps (id, runbook_id, step_order, action, command, outcome) VALUES ('46937092-8cbd-4b54-ab9f-d1ba37f83857', '090c1ad4-40c2-54d0-a0e1-627bf8ae496f', 2, 'Rule out real database capacity limits before treating it as a DB problem', NULL, 'Database-side connection count is far below its ceiling — the application pool is the constraint');
INSERT INTO runbook_steps (id, runbook_id, step_order, action, command, outcome) VALUES ('57e3e9f1-2b34-45ff-9f27-c9b99d275c4f', '090c1ad4-40c2-54d0-a0e1-627bf8ae496f', 5, 'Optionally lower PAYMENT_MAX_RETRIES to cap worst-case hold time as a stopgap', 'edit config.py: PAYMENT_MAX_RETRIES = 4', 'Bounds how long a slow charge can hold a connection while the code fix ships');
INSERT INTO runbook_steps (id, runbook_id, step_order, action, command, outcome) VALUES ('5afa5fa1-1064-4115-b005-79b5aa495fb6', '090c1ad4-40c2-54d0-a0e1-627bf8ae496f', 4, 'Move the acquire/release in checkout.py to wrap only the DB work, not the payment call (acquire after charge, or use a separate short-lived connection)', NULL, 'The scarce pool connection is no longer tied up across gateway retries; the pool stops draining under load');
INSERT INTO runbook_steps (id, runbook_id, step_order, action, command, outcome) VALUES ('6cdd717b-961b-45ee-bad6-8900a52f610f', '25b53e6b-449d-5971-94e5-6fd7ecb01a38', 2, 'Correlate against recent merges to metrics.py for a change to LATENCY_AGGREGATION', NULL, 'Identifies the merge that switched LATENCY_AGGREGATION from ''p99'' to ''avg'' as the cause of the blind dashboard');
INSERT INTO runbook_steps (id, runbook_id, step_order, action, command, outcome) VALUES ('6ff4b009-d6bf-4c30-893d-57d9d266f1dd', 'e6f2db0c-641b-545f-b9b7-db2463920e5e', 4, 'Verify backoff spacing is correct so retries are not amplifying load on the degraded gateway', 'grep ''config.loaded'' checkout-handler.log', 'Confirms PAYMENT_BASE_DELAY_SECONDS=0.5 (not a too-low value that would hammer the gateway between attempts)');
INSERT INTO runbook_steps (id, runbook_id, step_order, action, command, outcome) VALUES ('7cb50d01-a569-4b1a-85ed-cc679bc09d92', 'e6f2db0c-641b-545f-b9b7-db2463920e5e', 1, 'Confirm the retry storm and where it terminates', 'grep ''payment.exhausted'' checkout-handler.log', 'payment.retry climbing to attempt=8/8 then payment.exhausted attempts=8 confirms PaymentClient.charge is exhausting PAYMENT_MAX_RETRIES');
INSERT INTO runbook_steps (id, runbook_id, step_order, action, command, outcome) VALUES ('82c15c15-0f01-4355-b1bf-801ed87604dc', '2871adfe-4a5c-557d-b7b0-3ed28fe34410', 4, 'Watch FulfillmentQueue.depth() until it returns to near-zero baseline', NULL, 'Confirms full recovery with no checkout.enqueue_failed errors; queued orders were held, not dropped');
INSERT INTO runbook_steps (id, runbook_id, step_order, action, command, outcome) VALUES ('8e414696-585e-4131-9084-1eeb1e16fb60', '25b53e6b-449d-5971-94e5-6fd7ecb01a38', 4, 'Add a test asserting SLO metrics aggregate on p99 so the aggregation cannot silently regress again', NULL, 'Future merges that flip an SLO metric to avg fail CI before reaching production');
INSERT INTO runbook_steps (id, runbook_id, step_order, action, command, outcome) VALUES ('b08f9bac-abf5-4c08-94a6-25aa24ebaaaf', '25b53e6b-449d-5971-94e5-6fd7ecb01a38', 1, 'Check the aggregation on the metrics.latency line for the affected window', 'grep ''metrics.latency name=checkout.duration'' checkout-handler.log', 'Confirms agg=avg rather than agg=p99 — the mean is masking tail latency');
INSERT INTO runbook_steps (id, runbook_id, step_order, action, command, outcome) VALUES ('c259f73e-64f7-47e4-93a2-8c655a884c85', 'e6f2db0c-641b-545f-b9b7-db2463920e5e', 2, 'Determine whether GatewayTimeout is provider-wide or isolated to one AZ', NULL, 'Global impact points at a provider outage; single-AZ concentration points at a network/ACL regression instead');
INSERT INTO runbook_steps (id, runbook_id, step_order, action, command, outcome) VALUES ('c5a2b131-d047-45f0-a75e-618dbe9021c1', '090c1ad4-40c2-54d0-a0e1-627bf8ae496f', 1, 'Confirm the exhaustion signal and that in_use has reached size', 'grep ''db.pool.exhausted'' checkout-handler.log', 'Repeated db.pool.exhausted in_use=10 size=10 during the spike window confirms pool drain, not a DB outage');
INSERT INTO runbook_steps (id, runbook_id, step_order, action, command, outcome) VALUES ('cebbe877-1044-4f92-8d25-62db24f1b487', '2871adfe-4a5c-557d-b7b0-3ed28fe34410', 3, 'If the consumer is merely behind, scale it up to exceed FulfillmentQueue.enqueue''s arrival rate', 'kubectl scale deployment fulfillment-worker --replicas=12', 'Consumption rate exceeds arrival rate; queue depth drains back toward baseline');
INSERT INTO runbook_steps (id, runbook_id, step_order, action, command, outcome) VALUES ('d741a432-fce9-4221-ba8b-1f422f133a50', '25b53e6b-449d-5971-94e5-6fd7ecb01a38', 3, 'Revert LATENCY_AGGREGATION to p99 in metrics.py', 'edit metrics.py: LATENCY_AGGREGATION = "p99"', 'checkout.duration reports the tail again; the latency dashboard and alert regain visibility');

