INSERT INTO service_nodes (id, project, name, kind, summary, health_checks, updated_at) VALUES ('886eb091-1c88-5272-ac97-60faa1908c1f', 'sample', 'connection-pool', 'datastore', 'ConnectionPool (DB_POOL_SIZE=10) — held across PaymentClient.charge''s retry loop by CheckoutHandler.process (the code-only Incident A). No saturation metric is emitted for it today.', '{}', '2026-08-19 13:41:54.698606+00:00');
INSERT INTO service_nodes (id, project, name, kind, summary, health_checks, updated_at) VALUES ('c7d6d56a-46d0-5580-8a31-d17f65513620', 'sample', 'payment-gateway', 'external', 'PaymentClient.charge — the degrading dependency where the latency spike originates (one retry + backoff every GATEWAY_SLOW_EVERY-th charge).', '[{"intent": "p99", "metric": "payment_latency_ms", "threshold": 800}]', '2026-08-19 13:41:54.680741+00:00');
INSERT INTO service_nodes (id, project, name, kind, summary, health_checks, updated_at) VALUES ('cf7dc33d-945d-5c6d-954e-c347a04df83b', 'sample', 'fulfillment', 'service', 'FulfillmentQueue.enqueue — the healthy leaf; sub-millisecond append with no latency dynamics under demo-length runs.', '[{"intent": "p99", "metric": "enqueue_latency_ms", "threshold": 50}]', '2026-08-19 13:41:54.689513+00:00');
INSERT INTO service_nodes (id, project, name, kind, summary, health_checks, updated_at) VALUES ('f314342c-cf3b-50df-a62a-8ffeaa2b3d58', 'sample', 'checkout-service', 'service', 'The checkout request path (CheckoutHandler.process): acquires a pool connection, charges via the payment gateway, then enqueues fulfillment.', '[{"intent": "p99", "metric": "checkout_latency_ms", "threshold": 1000}]', '2026-08-19 13:41:54.663236+00:00');

